#pragma auto_inline(off)
template<> __declspec(noinline) bool CBasicString<char>::operator<(const CBasicString<char>& other) const
{
    const char* b=other.PData;
    const char* a=PData;
    for(;;) {
        if(*a==0 && *b==0) return false;
        if(*a<*b) return true;
        if(*a>*b) return false;
        ++a;
        ++b;
    }
}
